import pytest

from http_header_guard import validate

BAD_VALUES = [
  "hello\r\nX-Evil: 1",
  "hello\nX-Evil: 1",
  "hello\rX-Evil: 1",
  "hello\u0000world",
  "\u001b[31mred",
  "hello\u000bworld",
  "hello\fworld",
  "%0d%0aX-Evil: 1",
  "%250d%250aX-Evil: 1",
  "hello world",
  "hello world",
  "",
  "\r\n\r\n",
  "hello\tworld",
  "helloworld"
]


@pytest.mark.parametrize("value", BAD_VALUES)
def test_bad_value_is_rejected(value):
    with pytest.raises((ValueError, TypeError)):
        validate(value)
